'use client';

import * as React from 'react';
import { Sun, Moon } from 'lucide-react';
import { cn } from '@/lib/utils';

export interface ThemeToggleProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {}

export function ThemeToggle({ className, ...props }: ThemeToggleProps) {
  const [mounted, setMounted] = React.useState(false);
  const [isDark, setIsDark] = React.useState(false);

  React.useEffect(() => {
    setMounted(true);
    const checkDark = () => {
      const stored = typeof localStorage !== 'undefined' ? localStorage.getItem('treads_theme') : null;
      if (stored) {
        return stored === 'dark';
      }
      return typeof document !== 'undefined' && document.documentElement.classList.contains('dark');
    };
    setIsDark(checkDark());

    const handleThemeChange = (e: Event) => {
      const customEvent = e as CustomEvent<{ theme: 'light' | 'dark' }>;
      if (customEvent.detail?.theme) {
        setIsDark(customEvent.detail.theme === 'dark');
      } else {
        setIsDark(document.documentElement.classList.contains('dark'));
      }
    };

    window.addEventListener('themechange', handleThemeChange);
    return () => {
      window.removeEventListener('themechange', handleThemeChange);
    };
  }, []);

  const handleToggle = () => {
    const nextDark = !isDark;
    setIsDark(nextDark);

    if (nextDark) {
      document.documentElement.classList.add('dark');
      try {
        localStorage.setItem('treads_theme', 'dark');
      } catch {}
    } else {
      document.documentElement.classList.remove('dark');
      try {
        localStorage.setItem('treads_theme', 'light');
      } catch {}
    }

    window.dispatchEvent(
      new CustomEvent('themechange', {
        detail: { theme: nextDark ? 'dark' : 'light' },
      })
    );
  };

  return (
    <button
      type="button"
      onClick={handleToggle}
      aria-label={isDark ? 'Switch to light mode' : 'Switch to dark mode'}
      title={isDark ? 'Switch to light mode' : 'Switch to dark mode'}
      className={cn(
        'inline-flex h-9 w-9 items-center justify-center rounded-[var(--radius)] border border-border bg-card text-foreground shadow-xs transition-colors hover:bg-muted/60 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring cursor-pointer touch-manipulation',
        className
      )}
      {...props}
    >
      {mounted ? (
        isDark ? (
          <Moon className="h-4 w-4 transition-transform text-foreground" />
        ) : (
          <Sun className="h-4 w-4 transition-transform text-foreground" />
        )
      ) : (
        <span className="h-4 w-4 block opacity-0" aria-hidden="true" />
      )}
    </button>
  );
}

