    const onMapReady = () => {
      if (!isMounted) return;

      try {
        // 0. Initialize GeoJSON source for suggested loop route line (per ROUT-01, D-14)
        if (!map.getSource('suggested-route')) {
          map.addSource('suggested-route', {
            type: 'geojson',
