              type: 'Feature',
              properties: {},
              geometry: {
                type: 'LineString',
                coordinates: trackPoints.map((pt) => [pt.lng, pt.lat]),
              },
            },
          });
        }

        // 2. Add line layer styled with moss green (per D-11, GPS-02)
