args.ReplacementContent:
.nature-flutter {
  transform-origin: 50% 50%;
  transform-box: fill-box;
  animation: nature-flutter 0.28s ease-in-out infinite alternate;
}

/* Garden bee pollination patrol: hovering, dipping into bloom for pollen/nectar, and arcing to next bloom */
@keyframes bee-pollinate {
  0%, 100% {
    transform: translate3d(var(--x1, 0), var(--y1, 0), 0) rotate(-6deg);
  }
  16% {
    /* Dip into bloom center to collect pollen/nectar */
    transform: translate3d(var(--x1, 0), calc(var(--y1, 0) + 2.5px), 0) scale(0.95) rotate(4deg);
  }
  32% {
    /* Hover and brush pollen */
    transform: translate3d(calc(var(--x1, 0) + 1.5px), calc(var(--y1, 0) - 2.5px), 0) scale(1.02) rotate(-5deg);
  }
  50% {
    /* Smooth arc trajectory across patch to waypoint 2 */
    transform: translate3d(var(--mid-x, 0), var(--mid-y, 0), 0) scale(1.07) rotate(14deg);
  }
  68% {
    /* Arrive at next bloom */
    transform: translate3d(var(--x2, 0), var(--y2, 0), 0) rotate(-4deg);
  }
  78% {
    /* Dip into second bloom center */
    transform: translate3d(var(--x2, 0), calc(var(--y2, 0) + 2.5px), 0) scale(0.95) rotate(4deg);
  }
  88% {
    /* Hover and pollen brush */
    transform: translate3d(calc(var(--x2, 0) - 1.5px), calc(var(--y2, 0) - 2px), 0) scale(1.02) rotate(-3deg);
  }
}

.animate-bee-pollinate {
  animation: bee-pollinate var(--dur, 8s) cubic-bezier(0.42, 0, 0.58, 1) var(--delay, 0s) infinite;
  will-change: transform;
}

@media (prefers-reduced-motion: reduce) {
  .nature-sway, .nature-grass, .nature-wander, .nature-buzz, .nature-bob, .nature-flutter, .animate-bee-pollinate { animation: none; }
  .nature-cross { display: none; }
}

