'use client';

import * as React from 'react';
import { textToSvg } from 'tegaki';
import caveatBundle from 'tegaki/fonts/caveat';
import { useReducedMotion } from '@/hooks/use-reduced-motion';
import { cn } from '@/lib/utils';

export interface TegakiTextProps {
  text: string;
  className?: string;
  as?: 'h1' | 'h2' | 'span' | 'em' | 'p' | 'div';
  delay?: number;
  speed?: number;
  fontSize?: number;
  mode?: 'once' | 'loop' | 'static';
  showFlourish?: boolean;
}

export function TegakiText({
  text,
  className,
  as: Component = 'span',
  speed = 1.6,
  fontSize = 100,
  mode = 'once',
  showFlourish = false,
}: TegakiTextProps) {
  const shouldReduceMotion = useReducedMotion();
  const rawId = React.useId();
  const uid = React.useMemo(() => rawId.replace(/[^a-zA-Z0-9]/g, ''), [rawId]);

  const effectiveMode = shouldReduceMotion ? 'static' : mode;

  const svgHtml = React.useMemo(() => {
    try {
      const rawSvg = textToSvg(text, caveatBundle, {
        fontSize,
        color: 'currentColor',
        mode: effectiveMode,
        speed,
      });

      return rawSvg
        .replace(/tk-m(\d+)/g, `tk-${uid}-m$1`)
        .replace(/<svg\b([^>]*)>/, (_match, attrs) => {
          const cleanAttrs = attrs.replace(/\s*(width|height)="[^"]*"/g, '');
          return `<svg${cleanAttrs} class="inline-block h-[1.16em] w-auto max-w-full align-baseline overflow-visible" style="vertical-align: -0.16em;">`;
        });
    } catch (err) {
      console.warn('[TegakiText] Failed to render SVG:', err);
      return null;
    }
  }, [text, effectiveMode, speed, fontSize, uid]);

  if (!svgHtml) {
    return (
      <Component className={cn('font-handwriting inline-block select-text', className)}>
        {text}
      </Component>
    );
  }

  return (
    <Component
      className={cn('relative inline-flex flex-col items-start font-handwriting select-text', className)}
      role="text"
      aria-label={text}
    >
      <span className="sr-only">{text}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-center w-full"
        dangerouslySetInnerHTML={{ __html: svgHtml }}
      />

      {showFlourish && (
        <svg
          aria-hidden="true"
          className="w-full h-2 -mt-0.5 overflow-visible pointer-events-none"
          viewBox="0 0 100 8"
          preserveAspectRatio="none"
        >
          <path
            d="M 1 4 Q 35 7, 70 3 T 99 5"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.8"
            strokeLinecap="round"
            className="text-primary/70"
          />
        </svg>
      )}
    </Component>
  );
}

'use client';

import Link from 'next/link';
import { ArrowRight } from 'lucide-react';
import { buttonVariants } from '@/components/ui/button';
import { ThemeToggle } from '@/components/ui/theme-toggle';
import { AmbientWalk } from '@/components/landing/ambient-walk';
import { Meadow } from '@/components/landing/meadow';
import { TegakiText } from '@/components/motion/tegaki-text';
import { cn } from '@/lib/utils';

export default function HomePage() {
  return (
    <main className="paper-grain fixed inset-0 flex h-dvh max-h-dvh w-full flex-col items-center justify-center overflow-hidden overscroll-none bg-background px-6 text-center text-foreground select-none touch-none">
      <AmbientWalk />
      <Meadow />

      <div className="relative z-10 flex flex-col items-center">
        <p
          className="reveal font-mono text-[11px] uppercase tracking-[0.34em] text-muted-foreground"
          style={{ ['--i' as string]: 0 }}
        >
          Treads
        </p>

        <h1
          className="reveal mt-8 font-serif text-[clamp(3rem,9vw,7.5rem)] font-light leading-[0.98] tracking-tight"
          style={{ ['--i' as string]: 1 }}
        >
          Step outside.
          <br />
          <em className="font-normal text-primary not-italic inline-block">
            <TegakiText text="Notice what lives." as="span" speed={1.5} />
          </em>
        </h1>

        <Link
          href="/walk"
          className={cn(
            buttonVariants({ size: 'lg' }),
            'reveal group mt-12 h-12 rounded-full px-8 text-base shadow-md'
          )}
          style={{ ['--i' as string]: 3 }}
        >
          Begin a walk
          <ArrowRight className="h-4 w-4 transition-transform duration-300 group-hover:translate-x-0.5" />
        </Link>
      </div>

      <nav
        aria-label="Secondary"
        className="reveal absolute inset-x-0 bottom-6 z-10 flex items-center justify-center gap-6 text-sm text-muted-foreground"
        style={{ ['--i' as string]: 5 }}
      >
        <Link href="/collection" className="transition-colors hover:text-foreground">
          Life list
        </Link>
        <Link href="/journal" className="transition-colors hover:text-foreground">
          Journal
        </Link>
        <Link href="/settings" className="transition-colors hover:text-foreground">
          Settings
        </Link>
      </nav>

      <div className="absolute right-4 top-4 z-10 sm:right-6 sm:top-6">
        <ThemeToggle />
      </div>
    </main>
  );
}

