args.CodeContent:
'use client';

import * as React from 'react';
import { textToSvg } from 'tegaki';
import caveatBundle from 'tegaki/fonts/caveat';
import { useReducedMotion } from '@/hooks/use-reduced-motion';
import { cn } from '@/lib/utils';

export interface TegakiTextProps {
  text: string;
  className?: string;
  as?: 'h1' | 'h2' | 'span' | 'em' | 'p' | 'div';
  delay?: number;
  speed?: number;
  variant?: 'sans' | 'handwriting';
  showFlourish?: boolean;
}

export function TegakiText({
  text,
  className,
  as: Component = 'span',
  delay = 0.15,
  speed = 1.6,
  variant = 'sans',
  showFlourish = false,
}: TegakiTextProps) {
  const { prefersReducedMotion } = useReducedMotion();
  const rawId = React.useId();
  const uid = React.useMemo(() => rawId.replace(/[^a-zA-Z0-9]/g, ''), [rawId]);

  // Handwriting SVG renderer (used when variant === 'handwriting')
  const svgHtml = React.useMemo(() => {
    if (variant !== 'handwriting') return null;

    try {
      const rawSvg = textToSvg(text, caveatBundle, {
        fontSize: 100,
        color: 'currentColor',
        mode: prefersReducedMotion ? 'static' : 'once',
        speed,
      });

      return rawSvg
        .replace(/tk-m(\d+)/g, `tk-${uid}-m$1`)
        .replace(/<svg\b([^>]*)>/, (_match, attrs) => {
          const cleanAttrs = attrs.replace(/\s*(width|height)="[^"]*"/g, '');
          return `<svg${cleanAttrs} class="inline-block h-[1.16em] w-auto max-w-full align-baseline overflow-visible" style="vertical-align: -0.16em;">`;
        });
    } catch (err) {
      console.warn('[TegakiText] Failed to render handwriting SVG:', err);
      return null;
    }
  }, [text, variant, prefersReducedMotion, speed, uid]);

  // Sans-serif bold split-text kinetic animation (default)
  if (variant === 'sans') {
    const words = text.split(' ');
    let charCounter = 0;

    return (
      <Component
        className={cn(
          'relative inline-flex flex-col items-center select-text font-sans font-bold tracking-tight',
          className
        )}
        role="text"
        aria-label={text}
      >
        <span className="sr-only">{text}</span>
        <span aria-hidden="true" className="inline-flex flex-wrap items-center justify-center gap-x-[0.25em]">
          {words.map((word, wIdx) => {
            return (
              <span key={wIdx} className="inline-block whitespace-nowrap">
                {word.split('').map((char, cIdx) => {
                  const currentCharIdx = charCounter++;
                  const charDelay = prefersReducedMotion ? 0 : delay + currentCharIdx * 0.032;

                  return (
                    <span
                      key={cIdx}
                      className="kinetic-char"
                      style={
                        {
                          '--delay': `${charDelay}s`,
                        } as React.CSSProperties
                      }
                    >
                      {char}
                    </span>
                  );
                })}
              </span>
            );
          })}
        </span>

        {showFlourish && (
          <svg
            aria-hidden="true"
            className="w-full h-2 mt-0.5 overflow-visible pointer-events-none"
            viewBox="0 0 100 8"
            preserveAspectRatio="none"
          >
            <path
              d="M 1 4 Q 35 6.5, 70 3 T 99 4.5"
              fill="none"
              stroke="currentColor"
              strokeWidth="2.2"
              strokeLinecap="round"
              className="text-primary/75 animate-draw-flourish"
              style={
                {
                  '--flourish-delay': `${delay + (text.length * 0.032) + 0.1}s`,
                } as React.CSSProperties
              }
            />
          </svg>
        )}
      </Component>
    );
  }

  // Handwriting fallback / variant
  if (!svgHtml) {
    return (
      <Component className={cn('font-handwriting inline-block select-text', className)}>
        {text}
      </Component>
    );
  }

  return (
    <Component
      className={cn('relative inline-flex flex-col items-start font-handwriting select-text', className)}
      role="text"
      aria-label={text}
    >
      <span className="sr-only">{text}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-center w-full"
        dangerouslySetInnerHTML={{ __html: svgHtml }}
      />
    </Component>
  );
}

// Alias for convenience
export const AnimatedText = TegakiText;

