  as: Component = 'span',
  font = 'suez-one',
  speed = 4.5,
  loopHold = 3.5,
  glyphGap = 0.02,
  wordGap = 0.04,
  mode = 'loop',
  fontSize = 100,
}: TegakiTextProps) {
  const { prefersReducedMotion } = useReducedMotion();
  const rawId = React.useId();
  const uid = React.useMemo(() => rawId.replace(/[^a-zA-Z0-9]/g, ''), [rawId]);

  const bundle = FONT_BUNDLES[font] ?? suezBundle;
  const effectiveMode = prefersReducedMotion ? 'static' : mode;

  const svgHtml = React.useMemo(() => {
    try {
      const rawSvg = textToSvg(text, bundle, {
        fontSize,
        color: 'currentColor',
        mode: effectiveMode,
        speed,
        loopHold,
        timing: {
          glyphGap,
          wordGap,
        },
      });

      // Scope class and keyframe names with uid so multiple instances do not clash
      const scopedSvg = rawSvg
        .replace(/tk-a/g, `tk-${uid}-a`)
        .replace(/tk-m(\d+)/g, `tk-${uid}-m$1`)
        .replace(/<svg\b([^>]*)>/, (_match, attrs) => {
          const cleanAttrs = attrs.replace(/\s*(width|height)="[^"]*"/g, '');
          return `<svg${cleanAttrs} class="inline-block h-[1.14em] w-auto max-w-full align-baseline overflow-visible" style="vertical-align: -0.14em;">`;
        });

      return scopedSvg;
    } catch (err) {
      console.warn('[TegakiText] Failed to render Tegaki SVG:', err);
      return null;
    }
  }, [text, bundle, effectiveMode, speed, loopHold, glyphGap, wordGap, fontSize, uid]);

  if (!svgHtml) {
    return (
      <Component className={cn('font-serif inline-block select-text', className)}>
        {text}
      </Component>
    );
  }

  return (
    <Component
      className={cn('relative inline-flex flex-col items-center font-serif select-text', className)}
      role="text"
      aria-label={text}
    >
      <span className="sr-only">{text}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-center w-full"
        dangerouslySetInnerHTML={{ __html: svgHtml }}
      />
    </Component>
  );
}

