'use client';

import * as React from 'react';
import { motion } from 'motion/react';
import { useReducedMotion } from '@/hooks/use-reduced-motion';
import { cn } from '@/lib/utils';

export interface TegakiTextProps {
  text: string;
  className?: string;
  as?: 'h1' | 'h2' | 'span' | 'em' | 'p';
  delay?: number;
  showFlourish?: boolean;
}

export function TegakiText({
  text,
  className,
  as: Component = 'span',
  delay = 0.1,
  showFlourish = false,
}: TegakiTextProps) {
  const { prefersReducedMotion } = useReducedMotion();
  const [mounted, setMounted] = React.useState(false);

  React.useEffect(() => {
    setMounted(true);
  }, []);

  // Instant static render for SSR or reduced motion preference
  if (!mounted || prefersReducedMotion) {
    return (
      <Component className={cn('inline-block select-text', className)}>
        {text}
      </Component>
    );
  }

  return (
    <Component className={cn('relative inline-flex flex-col items-start select-text', className)}>
      <motion.span
        initial={{ clipPath: 'inset(0 100% 0 0)', opacity: 0.8 }}
        animate={{ clipPath: 'inset(0 0% 0 0)', opacity: 1 }}
        transition={{
          duration: 1.2,
          delay,
          ease: [0.25, 0.1, 0.25, 1],
        }}
        className="inline-block tracking-wide"
      >
        {text}
      </motion.span>

      {showFlourish && (
        <svg
          aria-hidden="true"
          className="w-full h-2 -mt-0.5 overflow-visible pointer-events-none"
          viewBox="0 0 100 8"
          preserveAspectRatio="none"
        >
          <motion.path
            d="M 1 4 Q 35 7, 70 3 T 99 5"
            fill="none"
            stroke="var(--primary)"
            strokeWidth="1.8"
            strokeLinecap="round"
            initial={{ pathLength: 0, opacity: 0 }}
            animate={{ pathLength: 1, opacity: 0.85 }}
            transition={{
              duration: 1.1,
              delay: delay + 0.3,
              ease: [0.4, 0, 0.2, 1],
            }}
          />
        </svg>
      )}
    </Component>
  );
}

export const AnimatedText = TegakiText;

'use client';

import Link from 'next/link';
import { ArrowRight } from 'lucide-react';
import { buttonVariants } from '@/components/ui/button';
import { ThemeToggle } from '@/components/ui/theme-toggle';
import { AmbientWalk } from '@/components/landing/ambient-walk';
import { Meadow } from '@/components/landing/meadow';
import { cn } from '@/lib/utils';

export default function HomePage() {
  return (
    <main className="paper-grain fixed inset-0 flex h-dvh max-h-dvh w-full flex-col items-center justify-center overflow-hidden overscroll-none bg-background px-6 text-center text-foreground select-none touch-none">
      <AmbientWalk />
      <Meadow />

      <div className="relative z-10 flex flex-col items-center">
        <p
          className="reveal font-mono text-[11px] uppercase tracking-[0.34em] text-muted-foreground"
          style={{ ['--i' as string]: 0 }}
        >
          Treads
        </p>

        <h1
          className="reveal mt-8 font-serif text-[clamp(3rem,9vw,7.5rem)] font-light leading-[0.98] tracking-tight"
          style={{ ['--i' as string]: 1 }}
        >
          Step outside.
          <br />
          <em className="font-normal text-primary">Notice what lives.</em>
        </h1>

        <Link
          href="/walk"
          className={cn(
            buttonVariants({ size: 'lg' }),
            'reveal group mt-12 h-12 rounded-full px-8 text-base shadow-md'
          )}
          style={{ ['--i' as string]: 3 }}
        >
          Begin a walk
          <ArrowRight className="h-4 w-4 transition-transform duration-300 group-hover:translate-x-0.5" />
        </Link>
      </div>

      <nav
        aria-label="Secondary"
        className="reveal absolute inset-x-0 bottom-6 z-10 flex items-center justify-center gap-6 text-sm text-muted-foreground"
        style={{ ['--i' as string]: 5 }}
      >
        <Link href="/collection" className="transition-colors hover:text-foreground">
          Life list
        </Link>
        <Link href="/journal" className="transition-colors hover:text-foreground">
          Journal
        </Link>
        <Link href="/settings" className="transition-colors hover:text-foreground">
          Settings
        </Link>
      </nav>

      <div className="absolute right-4 top-4 z-10 sm:right-6 sm:top-6">
        <ThemeToggle />
      </div>
    </main>
  );
}

